import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.Cwocg3GZ.js";const u=JSON.parse('{"title":"Secure your deployment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1788977236000}'),o={name:"guide/security.md"};function n(r,e,d,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="secure-your-deployment" tabindex="-1">Secure your deployment <a class="header-anchor" href="#secure-your-deployment" aria-label="Permalink to &quot;Secure your deployment&quot;">​</a></h1><p>The recommended deployment runs Boomerangz as its dedicated unprivileged account and grants access only to the ZFS roots it manages.</p><h2 id="zfs-delegation" tabindex="-1">ZFS delegation <a class="header-anchor" href="#zfs-delegation" aria-label="Permalink to &quot;ZFS delegation&quot;">​</a></h2><p>Use the narrowest source and destination roots that meet your needs.</p><h3 id="source-datasets" tabindex="-1">Source datasets <a class="header-anchor" href="#source-datasets" aria-label="Permalink to &quot;Source datasets&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  bookmark,destroy,hold,mount,release,send,snapshot,userprop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tank/data</span></span></code></pre></div><h3 id="destination-datasets" tabindex="-1">Destination datasets <a class="header-anchor" href="#destination-datasets" aria-label="Permalink to &quot;Destination datasets&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  compression,create,destroy,mount,mountpoint,readonly,receive,receive:append,userprop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  backup/boomerangz</span></span></code></pre></div><p>Add receive-property permissions only for properties you explicitly configure. Do not compensate for a delegation error with unrestricted <code>sudo</code> or by running the network-facing daemon as root.</p><h2 id="ssh" tabindex="-1">SSH <a class="header-anchor" href="#ssh" aria-label="Permalink to &quot;SSH&quot;">​</a></h2><ul><li>use the packaged <code>boomerangz</code> account and its <code>/usr/lib/boomerangz/boomerangz-shell</code> login shell for <code>ssh-shell</code>;</li><li>use a separate unprivileged <code>boomerangz-replication</code> account for direct SSH, with destination-only ZFS delegation and no <code>sudo</code> access;</li><li>use a separate Ed25519 key for each trust relationship;</li><li>verify host-key fingerprints out of band;</li><li>configure <code>identity_file</code> so Boomerangz selects only the intended key;</li><li>use <code>restrict</code> in <code>authorized_keys</code>, which disables forwarding, PTY, user-rc, agent forwarding, and X11 for that key;</li><li>do not replace the packaged restricted login shell with a general-purpose shell; the wrapper admits only <code>ssh-shell</code>, while <code>ssh_shell.replication_roots</code> limits the destination trees exposed through its API;</li><li>protect private keys from world read access and from group or world write access.</li></ul><h2 id="tcp-listeners-and-pairing" tabindex="-1">TCP listeners and pairing <a class="header-anchor" href="#tcp-listeners-and-pairing" aria-label="Permalink to &quot;TCP listeners and pairing&quot;">​</a></h2><p>TCP listeners are opt-in and always require TLS plus <code>token</code>, <code>mtls</code>, or <code>mtls+token</code> authentication.</p><ul><li><code>token</code> authorizes a scoped secret.</li><li><code>mtls</code> authenticates a client certificate.</li><li><code>mtls+token</code> requires both.</li></ul><p>Prefer <code>mtls+token</code> for replication over an untrusted network. Grant only the scopes a client needs: <code>status</code>, <code>trigger</code>, <code>replicate</code>, <code>prune</code>, or <code>admin</code>. The <code>admin</code> scope includes every operation.</p><p>Bind listeners only to intended interfaces and apply host firewall rules. An empty <code>replication_roots</code> list leaves a listener available for authenticated control but does not expose a destination for replication.</p><p>Boomerangz can manage its own private CA and renewable leaf certificates. For an externally managed server certificate, configure both <code>tls_cert</code> and <code>tls_key</code>. Clients use system trust roots unless <code>pairing_ca</code> supplies a specific CA. <code>pairing_pin_certificate = true</code> additionally pins the server public key while retaining normal CA, hostname, validity, and usage checks.</p><h2 id="protect-persistent-identity" tabindex="-1">Protect persistent identity <a class="header-anchor" href="#protect-persistent-identity" aria-label="Permalink to &quot;Protect persistent identity&quot;">​</a></h2><p><code>/var/lib/boomerangz/identity</code> establishes which installation may manage an existing dataset lineage. Back it up as part of the host&#39;s protected system state, but never deploy the same identity directory to two active hosts.</p><p>Credentials under <code>/etc/boomerangz/credentials.d</code> may contain private keys or tokens. Limit access to administrators and the <code>boomerangz</code> group.</p><h2 id="local-control-access" tabindex="-1">Local control access <a class="header-anchor" href="#local-control-access" aria-label="Permalink to &quot;Local control access&quot;">​</a></h2><p>The packaged service creates <code>/run/boomerangz/boomerangz.sock</code> as <code>boomerangz:boomerangz</code> with mode <code>0660</code>; its <code>/run/boomerangz</code> directory has mode <code>0750</code>. Add an administrative user to the group when they need to interact with the running instance without <code>sudo</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --append</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --groups</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USERNAME</span></span></code></pre></div><p>The user must sign out and back in before the new membership is available. Group membership grants access to all operations on the local control API, including state-changing operations; it is not read-only status access. Add only trusted daemon administrators, and do not make the socket or its containing directory world-accessible.</p>`,24)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
